import type { Activity } from '../../../schema/activity'

/**
 * A task from GET /Tasks ("Query the account's tasks."),
 * https://developers.ploomes.com/json/openapi.json. Documented fields read
 * here:
 *
 *   Id           "Task Id, automatically generated by the Database."
 *   Title        "Task title."
 *   Description  "Task description"
 *   ContactId    "Task contact id."
 *   DealId       "Task deal Id."
 *
 * `TypeId` is an id into /Tasks@Types, not a kind name, and `Lenght` has no
 * documented unit, so both stay in metadata. The spec lists no owner, due,
 * done, created or updated field on a task.
 */
export interface RawPloomesActivity {
  Id: number
  Title?: string | null
  Description?: string | null
  TypeId?: number
  ContactId?: number | null
  DealId?: number | null
  [key: string]: unknown
}

export function transformActivity(raw: RawPloomesActivity): Activity {
  return {
    id: String(raw.Id),
    subject: raw.Title ?? undefined,
    note: raw.Description ?? undefined,
    contact_id: raw.ContactId != null ? String(raw.ContactId) : undefined,
    deal_id: raw.DealId != null ? String(raw.DealId) : undefined,
    metadata: raw,
  }
}

export function untransformActivity(data: Partial<Activity>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  if (data.type !== undefined) out.Type = data.type
  if (data.subject !== undefined) out.Description = data.subject
  if (data.due_date !== undefined) out.DueDate = data.due_date
  if (data.done !== undefined) out.Done = data.done
  if (data.contact_id !== undefined) out.ContactId = Number(data.contact_id)
  if (data.deal_id !== undefined) out.DealId = Number(data.deal_id)
  if (data.owner_id !== undefined) out.OwnerId = Number(data.owner_id)
  return out
}
